import { Component, OnInit } from '@angular/core';
import { OrderTrackerService } from '../../services/order-tracker.service';
import { AuthService } from '../../services/auth.service';
import { NotificationService } from '../../services/notification.service';
import { OrderTrack, OrderNotification } from '../../Modals/EkartModels';

@Component({
  selector: 'app-order-tracker',
  templateUrl: './order-tracker.component.html',
  styleUrls: ['./order-tracker.component.css']
})
export class OrderTrackerComponent implements OnInit {
  activeTab: 'search' | 'my-orders' | 'admin-panel' | 'delivery-panel' = 'search';

  searchOrderId = '';
  loading = false;
  orderData: OrderTrack | null = null;
  orderHistory: OrderNotification[] = [];
  errorMessage = '';

  userOrders: OrderTrack[] = [];
  userOrdersLoading = false;

  adminOrders: OrderTrack[] = [];
  adminOrdersLoading = false;
  adminFilterStatus = 'ALL';

  deliveryOrders: OrderTrack[] = [];
  deliveryOrdersLoading = false;
  deliveryFilterStatus = 'ALL';

  constructor(
    private orderTrackerService: OrderTrackerService,
    private notificationService: NotificationService,
    public authService: AuthService
  ) {}

  ngOnInit(): void {
    if (this.authService.isDeliveryBoy) {
      this.activeTab = 'delivery-panel';
      this.loadDeliveryOrders();
    } else if (this.authService.isAdmin) {
      this.activeTab = 'admin-panel';
      this.loadAdminOrders();
    } else if (this.authService.isLoggedIn) {
      this.activeTab = 'my-orders';
      this.loadMyOrders();
    }
  }

  switchTab(tab: 'search' | 'my-orders' | 'admin-panel' | 'delivery-panel') {
    this.activeTab = tab;
    this.errorMessage = '';
    if (tab === 'my-orders') {
      this.loadMyOrders();
    } else if (tab === 'admin-panel') {
      this.loadAdminOrders();
    } else if (tab === 'delivery-panel') {
      this.loadDeliveryOrders();
    }
  }

  onTrackOrder() {
    if (!this.searchOrderId.trim()) {
      this.errorMessage = 'Please enter a valid Order ID (e.g. EK1004)';
      return;
    }

    this.loading = true;
    this.errorMessage = '';
    this.orderData = null;
    this.orderHistory = [];

    this.orderTrackerService.trackOrder(this.searchOrderId.trim()).subscribe(res => {
      this.loading = false;
      if (res.success && res.data) {
        this.orderData = res.data;
        this.loadOrderHistory(res.data.orderId);
      } else {
        this.errorMessage = res.message || 'Order ID not found.';
      }
    });
  }

  loadOrderHistory(orderId: string) {
    this.notificationService.getOrderHistory(orderId).subscribe(res => {
      if (res.success && res.data) {
        this.orderHistory = res.data;
      }
    });
  }

  loadMyOrders() {
    const userEmail = this.authService.currentUserValue?.email;
    if (!userEmail) return;

    this.userOrdersLoading = true;
    this.orderTrackerService.getMyOrders(userEmail).subscribe(res => {
      this.userOrdersLoading = false;
      if (res.success && res.data) {
        this.userOrders = res.data;
      }
    });
  }

  loadAdminOrders() {
    this.adminOrdersLoading = true;
    this.orderTrackerService.getAllOrdersAdmin().subscribe(res => {
      this.adminOrdersLoading = false;
      if (res.success && res.data) {
        this.adminOrders = res.data;
      }
    });
  }

  loadDeliveryOrders() {
    this.deliveryOrdersLoading = true;
    this.orderTrackerService.getDeliveryOrders().subscribe(res => {
      this.deliveryOrdersLoading = false;
      if (res.success && res.data) {
        this.deliveryOrders = res.data;
      }
    });
  }

  pickupOrderFromShop(order: OrderTrack) {
    const deliveryBoyName = this.authService.currentUserValue?.name || 'Delivery Executive';
    const deliveryBoyPhone = '+91 9876543210';

    this.orderTrackerService.pickupOrderDelivery(order.orderId, deliveryBoyName, deliveryBoyPhone).subscribe(res => {
      if (res.success && res.data) {
        order.status = 'OUT_FOR_DELIVERY';
        order.deliveryBoyName = res.data.deliveryBoyName;
        order.deliveryBoyPhone = res.data.deliveryBoyPhone;
        alert(`Order #${order.orderId} picked up from store! Out for home delivery.`);
      } else {
        alert(res.message || 'Failed to pick up order.');
      }
    });
  }

  completeHomeDelivery(order: OrderTrack) {
    this.orderTrackerService.completeOrderDelivery(order.orderId).subscribe(res => {
      if (res.success && res.data) {
        order.status = 'DELIVERED';
        alert(`Order #${order.orderId} successfully delivered to customer home! 🎉`);
      } else {
        alert(res.message || 'Failed to complete delivery.');
      }
    });
  }

  updateOrderStatusAdmin(order: OrderTrack, newStatus: string) {
    this.orderTrackerService.updateOrderStatusAdmin(
      order.orderId,
      newStatus,
      order.carrier || 'eKart Express Logistics',
      order.trackingNumber || ('TRK-' + Math.floor(1000000 + Math.random() * 9000000))
    ).subscribe(res => {
      if (res.success && res.data) {
        order.status = res.data.status;
        order.carrier = res.data.carrier;
        order.trackingNumber = res.data.trackingNumber;
        alert(`Order ${order.orderId} updated to ${newStatus}!`);
      } else {
        alert(res.message || 'Failed to update order status.');
      }
    });
  }

  get filteredAdminOrders(): OrderTrack[] {
    if (this.adminFilterStatus === 'ALL') {
      return this.adminOrders;
    }
    return this.adminOrders.filter(o => o.status === this.adminFilterStatus);
  }

  get filteredDeliveryOrders(): OrderTrack[] {
    if (this.deliveryFilterStatus === 'ALL') {
      return this.deliveryOrders;
    }
    return this.deliveryOrders.filter(o => o.status === this.deliveryFilterStatus);
  }

  isStepCompleted(step: string, targetOrder?: OrderTrack): boolean {
    const current = targetOrder ? targetOrder.status : this.orderData?.status;
    if (!current) return false;

    const rank: { [key: string]: number } = {
      'ORDER_RECEIVED': 1,
      'PROCESSING': 1,
      'ACCEPTED': 2,
      'SHIPPED': 3,
      'IN_TRANSIT': 3,
      'OUT_FOR_DELIVERY': 4,
      'DELIVERED': 5
    };

    const currentRank = rank[current] || 1;
    const stepRank = rank[step] || 1;

    return currentRank >= stepRank;
  }

  formatStatusBadge(status: string): string {
    switch (status) {
      case 'ORDER_RECEIVED': return '📌 Order Received';
      case 'ACCEPTED': return '🟢 Order Accepted (Ready for Pickup)';
      case 'SHIPPED': return '📦 Handed to Delivery Store';
      case 'OUT_FOR_DELIVERY': return '🛵 Out for Delivery to Home';
      case 'DELIVERED': return '✅ Delivered to Home';
      default: return status;
    }
  }
}
<div class="tracker-page">
  <div class="tracker-header">
    <h1>Order Fulfillment & <span class="highlight">Status Tracker</span></h1>
    <p>Real-time order tracking for customers, delivery execution for agents, and fulfillment control for administrators.</p>
  </div>

  <!-- NAVIGATION TABS -->
  <div class="tracker-tabs">
    <button [class.active]="activeTab === 'search'" (click)="switchTab('search')">
      🔍 Track by Order ID
    </button>
    <button *ngIf="authService.isLoggedIn && !authService.isAdmin && !authService.isDeliveryBoy" [class.active]="activeTab === 'my-orders'" (click)="switchTab('my-orders')">
      📋 My Orders ({{ userOrders.length }})
    </button>
    <button *ngIf="authService.isDeliveryBoy" [class.active]="activeTab === 'delivery-panel'" (click)="switchTab('delivery-panel')" class="delivery-tab-btn">
      🚚 Delivery Boy Dashboard
    </button>
    <button *ngIf="authService.isAdmin" [class.active]="activeTab === 'admin-panel'" (click)="switchTab('admin-panel')" class="admin-tab-btn">
      🛡️ Admin Orders Dashboard
    </button>
  </div>

  <!-- TAB 1: SEARCH ORDER ID -->
  <div *ngIf="activeTab === 'search'">
    <div class="search-card">
      <div class="search-form">
        <input type="text" [(ngModel)]="searchOrderId" placeholder="Enter Order ID (e.g. EK1004)..." class="search-input">
        <button (click)="onTrackOrder()" [disabled]="loading" class="btn btn-primary">
          {{ loading ? 'Searching...' : 'Track Order' }}
        </button>
      </div>
    </div>

    <div class="alert alert-danger" *ngIf="errorMessage">
      ⚠️ {{ errorMessage }}
    </div>

    <!-- TRACKED ORDER CARD -->
    <div class="order-details-card" *ngIf="orderData">
      <div class="card-top-bar">
        <div>
          <h2>Order #{{ orderData.orderId }}</h2>
          <span class="tracking-no">Tracking #: {{ orderData.trackingNumber || 'N/A' }}</span>
        </div>
        <div class="status-pill" [class.delivered]="orderData.status === 'DELIVERED'" [class.shipped]="orderData.status === 'SHIPPED' || orderData.status === 'OUT_FOR_DELIVERY'">
          {{ formatStatusBadge(orderData.status) }}
        </div>
      </div>

      <!-- TIMELINE PROGRESS STEPPER -->
      <div class="timeline">
        <div class="timeline-step" [class.completed]="isStepCompleted('ORDER_RECEIVED')">
          <div class="step-circle">✓</div>
          <div class="step-info">
            <h5>Order Placed</h5>
            <p>Received by eKart</p>
          </div>
        </div>

        <div class="timeline-step" [class.completed]="isStepCompleted('ACCEPTED')">
          <div class="step-circle">✓</div>
          <div class="step-info">
            <h5>Order Accepted</h5>
            <p>Approved by Admin</p>
          </div>
        </div>

        <div class="timeline-step" [class.completed]="isStepCompleted('SHIPPED')">
          <div class="step-circle">✓</div>
          <div class="step-info">
            <h5>Handed to Delivery Store</h5>
            <p>{{ orderData.carrier || 'Logistics Partner' }}</p>
          </div>
        </div>

        <div class="timeline-step" [class.completed]="isStepCompleted('OUT_FOR_DELIVERY')">
          <div class="step-circle">✓</div>
          <div class="step-info">
            <h5>Out for Delivery</h5>
            <p>On the way to home</p>
          </div>
        </div>

        <div class="timeline-step" [class.completed]="isStepCompleted('DELIVERED')">
          <div class="step-circle">✓</div>
          <div class="step-info">
            <h5>Delivered to Home</h5>
            <p>Successfully delivered</p>
          </div>
        </div>
      </div>

      <div class="details-grid">
        <div class="detail-item">
          <span class="label">Customer Name</span>
          <span class="val">{{ orderData.customerName || 'Valued Customer' }}</span>
        </div>
        <div class="detail-item">
          <span class="label">Delivery Executive</span>
          <span class="val">{{ orderData.deliveryBoyName || 'eKart Agent' }}</span>
        </div>
        <div class="detail-item">
          <span class="label">Estimated Delivery</span>
          <span class="val highlight-val">{{ orderData.estimatedDelivery || 'Within 3 Days' }}</span>
        </div>
        <div class="detail-item">
          <span class="label">Shipping Address</span>
          <span class="val">{{ orderData.shippingAddress }}</span>
        </div>
        <div class="detail-item">
          <span class="label">Total Amount</span>
          <span class="val">₹{{ orderData.totalAmount }}</span>
        </div>
      </div>

      <!-- ORDER ACTIVITY & MESSAGES THREAD -->
      <div class="order-messages-thread" *ngIf="orderHistory.length > 0">
        <h3>💬 Order Activity & Message History</h3>
        <div class="message-timeline">
          <div class="message-card" *ngFor="let item of orderHistory">
            <div class="message-header">
              <span class="sender-tag" [class.admin-tag]="item.senderRole === 'ADMIN'" [class.delivery-tag]="item.senderRole === 'DELIVERY'">
                {{ item.senderRole || 'SYSTEM' }}
              </span>
              <span class="message-title">{{ item.title }}</span>
              <span class="message-time">{{ item.timestamp | date:'shortTime' }} • {{ item.timestamp | date:'shortDate' }}</span>
            </div>
            <p class="message-body">{{ item.message }}</p>
          </div>
        </div>
      </div>
    </div>
  </div>

  <!-- TAB 2: MY ORDERS (USER VIEW) -->
  <div *ngIf="activeTab === 'my-orders'">
    <div class="section-card">
      <h2>My Order History</h2>
      <p class="sub-text">Check your current shipments and track real-time delivery status.</p>

      <div *ngIf="userOrdersLoading" class="loading-state">Loading your orders...</div>

      <div *ngIf="!userOrdersLoading && userOrders.length === 0" class="empty-state">
        🛒 You have not placed any orders yet. <a routerLink="/products">Start shopping now!</a>
      </div>

      <div class="user-order-card" *ngFor="let order of userOrders">
        <div class="card-top-bar">
          <div>
            <h3>Order #{{ order.orderId }}</h3>
            <span class="order-date">Placed on: {{ order.orderDate | date:'mediumDate' }}</span>
          </div>
          <div class="status-pill" [class.delivered]="order.status === 'DELIVERED'" [class.shipped]="order.status === 'SHIPPED' || order.status === 'OUT_FOR_DELIVERY'">
            {{ formatStatusBadge(order.status) }}
          </div>
        </div>

        <div class="timeline mini-timeline">
          <div class="timeline-step" [class.completed]="isStepCompleted('ORDER_RECEIVED', order)">
            <div class="step-circle">✓</div>
            <div class="step-info"><h5>Received</h5></div>
          </div>
          <div class="timeline-step" [class.completed]="isStepCompleted('ACCEPTED', order)">
            <div class="step-circle">✓</div>
            <div class="step-info"><h5>Accepted</h5></div>
          </div>
          <div class="timeline-step" [class.completed]="isStepCompleted('SHIPPED', order)">
            <div class="step-circle">✓</div>
            <div class="step-info"><h5>Handed to Delivery</h5></div>
          </div>
          <div class="timeline-step" [class.completed]="isStepCompleted('OUT_FOR_DELIVERY', order)">
            <div class="step-circle">✓</div>
            <div class="step-info"><h5>Out for Delivery</h5></div>
          </div>
          <div class="timeline-step" [class.completed]="isStepCompleted('DELIVERED', order)">
            <div class="step-circle">✓</div>
            <div class="step-info"><h5>Delivered</h5></div>
          </div>
        </div>

        <div class="user-order-meta">
          <div>📍 <strong>Address:</strong> {{ order.shippingAddress }}</div>
          <div>🛵 <strong>Delivery Executive:</strong> {{ order.deliveryBoyName || 'Assigned to eKart Logistics' }}</div>
          <div>💰 <strong>Total Amount:</strong> ₹{{ order.totalAmount }}</div>
        </div>
      </div>
    </div>
  </div>

  <!-- TAB 3: DELIVERY BOY DASHBOARD -->
  <div *ngIf="activeTab === 'delivery-panel'">
    <div class="admin-dashboard-card delivery-dashboard-card">
      <div class="admin-header-row">
        <div>
          <h2>🚚 Delivery Executive Portal</h2>
          <p>Pick up accepted orders from shop/store and finish delivery to customer home.</p>
        </div>
        <button (click)="loadDeliveryOrders()" class="btn btn-outline">🔄 Refresh Deliveries</button>
      </div>

      <!-- DELIVERY FILTER BUTTONS -->
      <div class="admin-filter-bar">
        <button [class.active]="deliveryFilterStatus === 'ALL'" (click)="deliveryFilterStatus = 'ALL'">All Orders ({{ deliveryOrders.length }})</button>
        <button [class.active]="deliveryFilterStatus === 'ACCEPTED'" (click)="deliveryFilterStatus = 'ACCEPTED'">🟢 Ready for Shop Pickup</button>
        <button [class.active]="deliveryFilterStatus === 'OUT_FOR_DELIVERY'" (click)="deliveryFilterStatus = 'OUT_FOR_DELIVERY'">🛵 In Delivery to Home</button>
        <button [class.active]="deliveryFilterStatus === 'DELIVERED'" (click)="deliveryFilterStatus = 'DELIVERED'">✅ Delivered</button>
      </div>

      <div *ngIf="deliveryOrdersLoading" class="loading-state">Loading delivery assignments...</div>

      <div *ngIf="!deliveryOrdersLoading && filteredDeliveryOrders.length === 0" class="empty-state">
        📭 No orders currently pending for this delivery status.
      </div>

      <!-- DELIVERY ORDERS TABLE -->
      <div class="admin-table-wrap" *ngIf="!deliveryOrdersLoading && filteredDeliveryOrders.length > 0">
        <table class="admin-orders-table">
          <thead>
            <tr>
              <th>Order ID</th>
              <th>Customer Name</th>
              <th>Home Delivery Address</th>
              <th>Amount</th>
              <th>Current Status</th>
              <th>Delivery Action</th>
            </tr>
          </thead>
          <tbody>
            <tr *ngFor="let order of filteredDeliveryOrders">
              <td>
                <strong>#{{ order.orderId }}</strong>
                <div class="trk-num">{{ order.trackingNumber }}</div>
              </td>
              <td>
                <div class="cust-name">{{ order.customerName || 'Customer' }}</div>
                <div class="cust-email">{{ order.customerEmail }}</div>
              </td>
              <td class="addr-cell">
                📍 <strong>{{ order.shippingAddress }}</strong>
              </td>
              <td><strong>₹{{ order.totalAmount }}</strong></td>
              <td>
                <span class="status-pill" [class.delivered]="order.status === 'DELIVERED'" [class.shipped]="order.status === 'SHIPPED' || order.status === 'OUT_FOR_DELIVERY'">
                  {{ formatStatusBadge(order.status) }}
                </span>
                <div class="delivery-agent-info" *ngIf="order.deliveryBoyName">
                  👤 {{ order.deliveryBoyName }}
                </div>
              </td>
              <td class="action-cell">
                <div class="action-buttons">
                  <button *ngIf="order.status === 'ACCEPTED' || order.status === 'ORDER_RECEIVED' || order.status === 'SHIPPED'" (click)="pickupOrderFromShop(order)" class="btn-action btn-transit" title="Pick up package from store">
                    📦 Pick Up from Shop
                  </button>

                  <button *ngIf="order.status === 'OUT_FOR_DELIVERY'" (click)="completeHomeDelivery(order)" class="btn-action btn-deliver" title="Finish delivery to customer home">
                    ✅ Finish Delivery to Home
                  </button>

                  <span *ngIf="order.status === 'DELIVERED'" class="delivered-text">
                    🎉 Delivered & Complete
                  </span>
                </div>
              </td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  </div>

  <!-- TAB 4: ADMIN ORDERS DASHBOARD -->
  <div *ngIf="activeTab === 'admin-panel'">
    <div class="admin-dashboard-card">
      <div class="admin-header-row">
        <div>
          <h2>🛡️ Admin Order Fulfillment Dashboard</h2>
          <p>Accept orders, track delivery boy assignments, and monitor delivery progress.</p>
        </div>
        <button (click)="loadAdminOrders()" class="btn btn-outline">🔄 Refresh Orders</button>
      </div>

      <!-- STATUS FILTER BUTTONS -->
      <div class="admin-filter-bar">
        <button [class.active]="adminFilterStatus === 'ALL'" (click)="adminFilterStatus = 'ALL'">All Orders ({{ adminOrders.length }})</button>
        <button [class.active]="adminFilterStatus === 'ORDER_RECEIVED'" (click)="adminFilterStatus = 'ORDER_RECEIVED'">📌 New Orders</button>
        <button [class.active]="adminFilterStatus === 'ACCEPTED'" (click)="adminFilterStatus = 'ACCEPTED'">🟢 Accepted</button>
        <button [class.active]="adminFilterStatus === 'OUT_FOR_DELIVERY'" (click)="adminFilterStatus = 'OUT_FOR_DELIVERY'">🛵 With Delivery Boy</button>
        <button [class.active]="adminFilterStatus === 'DELIVERED'" (click)="adminFilterStatus = 'DELIVERED'">✅ Delivered</button>
      </div>

      <div *ngIf="adminOrdersLoading" class="loading-state">Loading customer orders...</div>

      <div *ngIf="!adminOrdersLoading && filteredAdminOrders.length === 0" class="empty-state">
        📭 No customer orders found for this status.
      </div>

      <!-- ADMIN ORDERS TABLE -->
      <div class="admin-table-wrap" *ngIf="!adminOrdersLoading && filteredAdminOrders.length > 0">
        <table class="admin-orders-table">
          <thead>
            <tr>
              <th>Order ID</th>
              <th>Customer</th>
              <th>Shipping Address</th>
              <th>Total</th>
              <th>Assigned Delivery Executive</th>
              <th>Current Status</th>
              <th>Admin Action</th>
            </tr>
          </thead>
          <tbody>
            <tr *ngFor="let order of filteredAdminOrders">
              <td>
                <strong>#{{ order.orderId }}</strong>
                <div class="trk-num">{{ order.trackingNumber }}</div>
              </td>
              <td>
                <div class="cust-name">{{ order.customerName || 'Customer' }}</div>
                <div class="cust-email">{{ order.customerEmail }}</div>
              </td>
              <td class="addr-cell">{{ order.shippingAddress }}</td>
              <td><strong>₹{{ order.totalAmount }}</strong></td>
              <td>
                <div class="cust-name">{{ order.deliveryBoyName || 'Unassigned' }}</div>
                <div class="cust-email" *ngIf="order.deliveryBoyPhone">{{ order.deliveryBoyPhone }}</div>
              </td>
              <td>
                <span class="status-pill" [class.delivered]="order.status === 'DELIVERED'" [class.shipped]="order.status === 'SHIPPED' || order.status === 'OUT_FOR_DELIVERY'">
                  {{ formatStatusBadge(order.status) }}
                </span>
              </td>
              <td class="action-cell">
                <div class="action-buttons">
                  <button *ngIf="order.status === 'ORDER_RECEIVED'" (click)="updateOrderStatusAdmin(order, 'ACCEPTED')" class="btn-action btn-accept" title="Accept Customer Order">
                    🟢 Accept Order
                  </button>

                  <button *ngIf="order.status === 'ACCEPTED'" (click)="updateOrderStatusAdmin(order, 'SHIPPED')" class="btn-action btn-ship" title="Handover product to delivery store">
                    📦 Ready at Delivery Store
                  </button>

                  <button *ngIf="order.status === 'SHIPPED'" (click)="updateOrderStatusAdmin(order, 'OUT_FOR_DELIVERY')" class="btn-action btn-transit" title="Send for Home Delivery">
                    🛵 Send Out for Delivery
                  </button>

                  <button *ngIf="order.status === 'OUT_FOR_DELIVERY'" (click)="updateOrderStatusAdmin(order, 'DELIVERED')" class="btn-action btn-deliver" title="Mark order delivered to customer home">
                    ✅ Mark Delivered
                  </button>

                  <span *ngIf="order.status === 'DELIVERED'" class="delivered-text">
                    🎉 Delivered & Complete
                  </span>
                </div>
              </td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  </div>
</div>
